import kotlin.math.sqrt

var res = mutableListOf<Int>()

fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    val k = scanner.nextInt()

    solve(n, k)
    if (res.size != k) {
        println(-1)
        return
    }
    var check = 1
    for (el in res) {
        check *= el
    }
    if (check != n) {
        println(-1)
        return
    }
    for (i in res.indices) {
        if (i == res.lastIndex) {
            println(res[i])
        } else {
            print("${res[i]} ")
        }
    }
