    if (n == 1) {
        return
    }
    if (k == 1) {
        res.add(n)
        return
    }
    val limit = sqrt(n.toDouble()).toInt() + 1
    for (i in 2..limit) {
        if (n % i == 0) {
            res.add(i)
            solve(n / i, k - 1)
            return
        }
    }
}

